class Solution:
    def isAnagram(self, s, t):
        if len(s) != len(t):
            return False
        counts = {}
        for char in s:
            counts[char] = counts.get(char, 0) + 1
        for char in t:
            counts[char] = counts.get(char, 0) - 1
            if counts[char] < 0:
                return False
        return True
